function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));ctx.translate(-cam.x,-cam.y);drawGround();drawDecor();drawMist();drawProjectiles();for(const m of minions)drawGhoul(m);drawHero();drawPlayer();drawParticles();ctx.restore();drawScreenFX();}
function drawGround(){ctx.fillStyle='#18201e';ctx.fillRect(0,0,world.w,world.h);const g=ctx.createLinearGradient(0,0,world.w,world.h);g.addColorStop(0,'#1c2521');g.addColorStop(.52,'#20231e');g.addColorStop(1,'#151c1c');ctx.fillStyle=g;ctx.fillRect(0,0,world.w,world.h);
 // subtle worn-earth texture
 for(let i=0;i<stones.length;i++){const s=stones[i];ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.rot);ctx.fillStyle=`rgba(136,147,111,${s.a})`;ctx.beginPath();ctx.ellipse(0,0,s.r,s.r*.43,0,0,Math.PI*2);ctx.fill();ctx.restore();}
 ctx.strokeStyle='rgba(195,203,157,.045)';ctx.lineWidth=2;for(let i=0;i<22;i++){let x=(i*173+80)%world.w,y=(i*251+120)%world.h;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+rand(-30,30),y+rand(8,27),x+rand(-24,24),y+rand(35,65));ctx.stroke();}
 // perimeter of the playable graveyard
 ctx.strokeStyle='#c9d0ad24';ctx.lineWidth=3;ctx.strokeRect(12,12,world.w-24,world.h-24);ctx.strokeStyle='#090d0d';ctx.lineWidth=16;ctx.strokeRect(0,0,world.w,world.h);
}
function drawDecor(){for(const t of trees){ctx.save();ctx.translate(t.x,t.y);ctx.fillStyle='#0d1514';ctx.beginPath();ctx.ellipse(4,9,t.r*.72,t.r*.38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=`rgba(10,22,20,${t.a})`;ctx.beginPath();ctx.arc(0,0,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25302a';ctx.beginPath();ctx.arc(-t.r*.24,-t.r*.22,t.r*.7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#334037';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(-t.r*.35,-t.r*.32,t.r*.35,0,Math.PI*2);ctx.fill();ctx.restore();}
 // tombstones and candles
 for(let i=0;i<25;i++){let x=(i*317+160)%world.w,y=(i*197+90)%world.h;if(Math.hypot(x-player.x,y-player.y)<100||Math.hypot(x-hero.x,y-hero.y)<70)continue;let r=8+(i%3)*2;ctx.save();ctx.translate(x,y);ctx.fillStyle='#101715';ctx.fillRect(-r-3,3,r*2+6,3);ctx.fillStyle=i%4===0?'#687263':'#424d48';ctx.beginPath();ctx.moveTo(-r,-r*.2);ctx.quadraticCurveTo(-r,-r*1.25,0,-r*1.25);ctx.quadraticCurveTo(r,-r*1.25,r,-r*.2);ctx.lineTo(r,r*.6);ctx.lineTo(-r,r*.6);ctx.closePath();ctx.fill();ctx.strokeStyle='#9ba38a35';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#bac1a242';ctx.font=`${r*.9}px serif`;ctx.textAlign='center';ctx.fillText('†',0,r*.18);if(i%7===0){ctx.shadowColor='#d0b779';ctx.shadowBlur=14;ctx.fillStyle='#facf7b';ctx.beginPath();ctx.arc(r+8,2,2.4,0,Math.PI*2);ctx.fill();}ctx.restore();}
 // a broken iron fence accent around the edge
 ctx.strokeStyle='#49524b';ctx.lineWidth=2;for(let x=45;x<world.w-20;x+=48){ctx.beginPath();ctx.moveTo(x,18);ctx.lineTo(x,33);ctx.moveTo(x,world.h-18);ctx.lineTo(x,world.h-33);ctx.stroke();}
}
function drawMist(){for(const f of mist){let x=f.x+Math.sin(elapsed*.18+f.phase)*28,y=f.y+Math.cos(elapsed*.16+f.phase)*16;let grad=ctx.createRadialGradient(x,y,0,x,y,f.r);grad.addColorStop(0,'rgba(162,185,159,.09)');grad.addColorStop(1,'rgba(162,185,159,0)');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(x,y,f.r,0,Math.PI*2);ctx.fill();}}
function drawProjectiles(){for(const b of bolts){ctx.save();ctx.shadowColor='#ffc579';ctx.shadowBlur=15;ctx.strokeStyle='#ffd492';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(b.x-b.vx*.028,b.y-b.vy*.028);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(b.x,b.y,2.4,0,Math.PI*2);ctx.fill();ctx.restore();}}
function drawGhoul(m){ctx.save();ctx.translate(m.x,m.y+Math.sin(m.phase)*1.6);if(m.hit>0)ctx.globalAlpha=.55;let s=m.type==='brute'?1.3:1;ctx.scale(s,s);ctx.fillStyle='#070b0b99';ctx.beginPath();ctx.ellipse(0,8,12,5,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=frenzy>0?'#ff8b6a':'#74836d';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-5,3);ctx.lineTo(-7,9);ctx.moveTo(5,3);ctx.lineTo(7,9);ctx.stroke();ctx.fillStyle=m.type==='brute'?'#565b48':'#65745c';ctx.beginPath();ctx.ellipse(0,0,9,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#778269';ctx.beginPath();ctx.arc(0,-7,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#211c21';ctx.beginPath();ctx.arc(-2.6,-7,1.8,0,Math.PI*2);ctx.arc(2.6,-7,1.8,0,Math.PI*2);ctx.fill();ctx.fillStyle=frenzy>0?'#ff6a63':'#d7e88b';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=7;ctx.beginPath();ctx.arc(-2.6,-7,1,0,Math.PI*2);ctx.arc(2.6,-7,1,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawHero(){ctx.save();ctx.translate(hero.x,hero.y);ctx.fillStyle='#05090a9e';ctx.beginPath();ctx.ellipse(0,11,14,6,0,0,Math.PI*2);ctx.fill();if(hero.invuln>0&&Math.floor(elapsed*24)%2)ctx.globalAlpha=.5;ctx.fillStyle='#b9b8a9';ctx.beginPath();ctx.arc(0,-7,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#433b39';ctx.beginPath();ctx.moveTo(-5,-10);ctx.lineTo(-7,-17);ctx.lineTo(3,-15);ctx.lineTo(7,-9);ctx.closePath();ctx.fill();ctx.fillStyle='#b34b4c';ctx.beginPath();ctx.moveTo(-5,-1);ctx.lineTo(5,-1);ctx.lineTo(9,9);ctx.lineTo(-9,9);ctx.closePath();ctx.fill();ctx.strokeStyle='#ddd0b6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(7,-2);ctx.lineTo(14,-7);ctx.stroke();ctx.fillStyle='#f9d79c';ctx.shadowColor='#f9b960';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(14,-7,2,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);const moving=Math.hypot(player.vx,player.vy)>30;ctx.rotate(Math.sin(elapsed*9)*.025*(moving?1:0));ctx.fillStyle='#05090aa8';ctx.beginPath();ctx.ellipse(0,11,21,9,0,0,Math.PI*2);ctx.fill();ctx.shadowColor=frenzy>0?'#fa6b62':'#bcf064';ctx.shadowBlur=frenzy>0?24:14;ctx.fillStyle='#19251e';ctx.strokeStyle=frenzy>0?'#ff9374':'#c7e77b';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#d5e894';ctx.beginPath();ctx.arc(-5,-2,2,0,Math.PI*2);ctx.arc(5,-2,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#cad790';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,-13);ctx.lineTo(-11,-22);ctx.lineTo(-2,-16);ctx.moveTo(7,-13);ctx.lineTo(11,-22);ctx.lineTo(2,-16);ctx.stroke();ctx.restore();}
function drawParticles(){for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
function drawScreenFX(){// restrained lunar vignette and danger wash
 if(state!=='playing')return;let hp=hero.hp/hero.max;if(hp<.34){ctx.fillStyle=`rgba(113,28,40,${(.34-hp)*.35})`;ctx.fillRect(0,0,W,H);}if(frenzy>0){ctx.strokeStyle=`rgba(255,111,91,${.2+Math.sin(elapsed*12)*.08})`;ctx.lineWidth=3;ctx.strokeRect(5,5,W-10,H-10);}}
const keys=new Set();addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='q')summon();if(k===' '){if(state==='playing')useFrenzy();}if(k==='escape'||k==='p'){if(state==='playing'||state==='paused')togglePause();}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function pointerPos(e){let r=canvas.getBoundingClientRect();return{x:e.clientX+cam.x-r.left,y:e.clientY+cam.y-r.top};}
canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;aim=pointerPos(e);if(e.button===2){summon();return;}if(e.pointerType==='touch'){canvas.setPointerCapture(e.pointerId);}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
// Dragging the ground provides a direct rally command; movement keys remain available.
let drag=null;canvas.addEventListener('pointerdown',e=>{if(state==='playing'&&e.pointerType!=='touch'&&e.button===0)drag={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointermove',e=>{if(drag&&state==='playing'){let dx=e.clientX-drag.x,dy=e.clientY-drag.y;player.x=clamp(player.x+dx,25,world.w-25);player.y=clamp(player.y+dy,25,world.h-25);drag={x:e.clientX,y:e.clientY};}});addEventListener('pointerup',()=>drag=null);
$('startBtn').addEventListener('click',start);$('againBtn').addEventListener('click',start);$('resumeBtn').addEventListener('click',togglePause);$('pauseAgainBtn').addEventListener('click',start);$('touchSummon').addEventListener('pointerdown',e=>{e.preventDefault();summon();});$('touchFrenzy').addEventListener('pointerdown',e=>{e.preventDefault();useFrenzy();});
const stick=$('stick');stick.addEventListener('pointerdown',e=>{e.preventDefault();stick.setPointerCapture(e.pointerId);joystick.active=true;setStick(e);});stick.addEventListener('pointermove',e=>{if(joystick.active)setStick(e);});stick.addEventListener('pointerup',()=>{joystick={active:false,x:0,y:0};});stick.addEventListener('pointercancel',()=>{joystick={active:false,x:0,y:0};});function setStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=39;if(d>max){dx*=max/d;dy*=max/d;}joystick.x=dx/max;joystick.y=dy/max;}
makeWorld();draw();
})();
